CREATE SCHEMA db_master;

CREATE TABLE mscompanycode (
	company_code varchar(10) NOT NULL,
	company_name varchar(50) NOT NULL,
	"createdBy" varchar(50) NOT NULL,
	"updatedBy" varchar(50) NOT NULL,
	created_at timestamp(6) NULL,
	updated_at timestamp(6) NULL,
	sap_chart_of_account varchar(5) NULL,
	CONSTRAINT mscompanycode_pkey PRIMARY KEY (company_code)
);



CREATE TABLE msdepartement (
	"deptID" serial4 NOT NULL,
	"deptCode" varchar(10) NOT NULL,
	"deptName" varchar(50) NOT NULL,
	"createdBy" varchar(50) DEFAULT 'sysSystem'::character varying NOT NULL,
	"updatedBy" varchar(50) DEFAULT 'sysSystem'::character varying NOT NULL,
	created_at timestamp(6) DEFAULT CURRENT_TIMESTAMP NULL,
	updated_at timestamp(6) DEFAULT CURRENT_TIMESTAMP NULL,
	CONSTRAINT "msdepartement_deptCode_unique" UNIQUE ("deptCode"),
	CONSTRAINT msdepartement_pkey PRIMARY KEY ("deptID")
);

