CREATE TABLE msshift (
	id serial4 NOT NULL,
	"siteId" varchar(5) NOT NULL,
	shift int4 DEFAULT 0 NOT NULL,
	start_time time NULL,
	end_time time NULL,
	created_by varchar(15) NULL,
	created_at timestamp NULL,
	updated_by varchar(15) NULL,
	updated_at timestamp NULL,
	CONSTRAINT msshift_pkey PRIMARY KEY (id)
);



CREATE TABLE mssite (
	"siteID" varchar(10) NOT NULL,
	"companyID" varchar(10) NOT NULL,
	"siteName" varchar(50) NOT NULL,
	"createdBy" varchar(50) NOT NULL,
	"updatedBy" varchar(50) NOT NULL,
	created_at timestamp(6) NULL,
	updated_at timestamp(6) NULL,
	is_headoffice information_schema."yes_or_no" DEFAULT 'NO'::character varying NOT NULL,
	deleted_at timestamp(6) NULL,
	CONSTRAINT mssite_pkey PRIMARY KEY ("siteID"),
	CONSTRAINT companycode_fk FOREIGN KEY ("companyID") REFERENCES mscompanycode(company_code) ON DELETE CASCADE
);



CREATE TABLE msemployee (
	"EmployeeID" varchar(10) NOT NULL,
	"EmployeeName" varchar(50) NOT NULL,
	"SiteId" varchar(10) NOT NULL,
	"DeptID" int4 NOT NULL,
	created_at timestamp(6) NULL,
	updated_at timestamp(6) NULL,
	"Class" varchar(5) NULL,
	"Status" varchar(8) NULL,
	"PositionName" varchar(60) NULL,
	CONSTRAINT msemployee_pkey PRIMARY KEY ("EmployeeID"),
	CONSTRAINT departement_fk FOREIGN KEY ("DeptID") REFERENCES msdepartement("deptID") ON DELETE CASCADE,
	CONSTRAINT site_fk FOREIGN KEY ("SiteId") REFERENCES mssite("siteID") ON DELETE CASCADE
);


CREATE TABLE msequipment (
	equipment_id varchar(30) NOT NULL,
	manufacturer varchar(30) NULL,
	model_number varchar(30) NULL,
	tank_capacity numeric(9, 2) NULL,
	category varchar(2) NULL,
	category_desc varchar(45) NULL,
	auth_group varchar(3) NULL,
	auth_text varchar(45) NULL,
	company_code varchar(4) NULL,
	"createdBy" varchar(50) NULL,
	created_at timestamp(6) NULL,
	"updatedBy" varchar(50) NULL,
	updated_at timestamp(6) NULL,
	deleted information_schema."yes_or_no" DEFAULT 'NO'::character varying NULL,
	CONSTRAINT msequipment_pkey PRIMARY KEY (equipment_id)
);



CREATE TABLE ms_base_ob_and_distance (
	id serial4 NOT NULL,
	plan_date date NOT NULL,
	site bpchar(3) NOT NULL,
	base_ob numeric(5, 4) DEFAULT 0.0000 NOT NULL,
	pengurang_jarak int2 DEFAULT 0 NOT NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	base_over_distance numeric(5, 4) DEFAULT 0.0000 NOT NULL,
	CONSTRAINT ms_base_ob_and_distance_pk PRIMARY KEY (id)
);



CREATE TABLE ms_fuel_ratio_coal (
	id serial4 NOT NULL,
	plan_date date NOT NULL,
	site bpchar(3) NOT NULL,
	fr_coal_getting numeric(5, 4) DEFAULT 0.0000 NOT NULL,
	fr_coal_hauling numeric(5, 4) DEFAULT 0.0000 NOT NULL,
	fr_coal_haul_road numeric(5, 4) DEFAULT 0.0000 NOT NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	CONSTRAINT ms_fuel_ratio_coal_pk PRIMARY KEY (id)
);



CREATE TABLE ms_material (
	id serial4 NOT NULL,
	material_name varchar(50) NOT NULL,
	created_by varchar(15) NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_by varchar(15) NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	CONSTRAINT ms_material_pk PRIMARY KEY (id)
);




CREATE TABLE ms_pit_location (
	id serial4 NOT NULL,
	site bpchar(3) NOT NULL,
	location_name varchar(25) NOT NULL,
	parent_id int4 DEFAULT 0 NULL,
	created_by varchar(15) NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_by varchar(15) NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	CONSTRAINT ms_pit_location_pk PRIMARY KEY (id)
);




CREATE TABLE ms_productivity_problem (
	id bigserial NOT NULL,
	prod_problem varchar(60) NOT NULL,
	problem_description text NULL,
	created_by varchar(10) DEFAULT 'system'::character varying NULL,
	created_at timestamp DEFAULT now() NULL,
	updated_by varchar(10) DEFAULT 'system'::character varying NULL,
	updated_at timestamp DEFAULT now() NULL,
	deleted_at timestamp NULL,
	CONSTRAINT ms_productivity_plan_pk PRIMARY KEY (id)
);




CREATE TABLE ms_status_category (
	id bigserial NOT NULL,
	status_category varchar(30) NOT NULL,
	created_at timestamp DEFAULT now() NULL,
	updated_at timestamp DEFAULT now() NULL,
	deleted_at timestamp NULL,
	CONSTRAINT ms_status_category_pk PRIMARY KEY (id)
);




CREATE TABLE ms_status_dedicated (
	id bigserial NOT NULL,
	dedicated_value varchar(30) NOT NULL,
	created_at timestamp DEFAULT now() NULL,
	updated_at timestamp DEFAULT now() NULL,
	deleted_at timestamp NULL,
	CONSTRAINT ms_status_dedicated_pk PRIMARY KEY (id)
);




CREATE TABLE ms_time_range (
	id serial4 NOT NULL,
	time_range varchar(10) NOT NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	start_time time NULL,
	end_time time NULL,
	CONSTRAINT ms_time_range_pk PRIMARY KEY (id)
);




CREATE TABLE ms_status_item_category (
	id bigserial NOT NULL,
	category_id int4 NOT NULL,
	item_category varchar(30) NOT NULL,
	created_at timestamp DEFAULT now() NULL,
	updated_at timestamp DEFAULT now() NULL,
	deleted_at timestamp NULL,
	required_operator information_schema."yes_or_no" DEFAULT 'NO'::character varying COLLATE "C" NULL,
	dedicated int4 NULL,
	CONSTRAINT ms_status_item_category_pk PRIMARY KEY (id),
	CONSTRAINT ms_status_item_category_dedicated_fk FOREIGN KEY (dedicated) REFERENCES ms_status_dedicated(id) ON DELETE CASCADE,
	CONSTRAINT ms_status_item_category_fk FOREIGN KEY (category_id) REFERENCES ms_status_category(id)
);




CREATE TABLE ms_submaterial (
	id serial4 NOT NULL,
	site bpchar(3) NOT NULL,
	submaterial_name varchar(25) NOT NULL,
	material_id int4 NULL,
	factor numeric(3, 1) DEFAULT 0.0 NULL,
	created_by varchar(15) NULL,
	created_at timestamp(6) DEFAULT now() NULL,
	updated_by varchar(15) NULL,
	updated_at timestamp(6) DEFAULT now() NULL,
	deleted_at timestamp(6) NULL,
	CONSTRAINT ms_submaterial_pk PRIMARY KEY (id),
	CONSTRAINT ms_submaterial_material_fk FOREIGN KEY (material_id) REFERENCES ms_material(id) ON DELETE CASCADE
);



